CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE names (
  id int  PRIMARY KEY,
  n  text NOT NULL
);

INSERT INTO names (id, n) VALUES
  (1, 'Sarah Connor'), (2, 'Sara Conner'), (3, 'Sean Connery'),
  (4, 'Sarah Connelly'), (5, 'Michael Bay'), (6, 'Mike Bays');

CREATE INDEX names_n_gin  ON names USING gin  (n gin_trgm_ops);
CREATE INDEX names_n_gist ON names USING gist (n gist_trgm_ops);

SELECT id, n
FROM names
WHERE n ILIKE '%conn%'
ORDER BY id;

SELECT id, n, n <-> 'Sarah Conner' AS dist
FROM names
ORDER BY dist, id
LIMIT 3;

-- Either index can serve the ILIKE filter: both operator classes support
-- LIKE/ILIKE/regex/% as search predicates. Only the GiST index can serve the
-- second query, because ORDER BY <-> needs an ordering operator, and GIN has
-- none -- it maps keys to rows and has no notion of distance to a query point.

