-- v3c07_types_keys / review1 — enum or lookup table
CREATE TYPE ticket_state AS ENUM ('open', 'triaged', 'closed');

CREATE TABLE t_enum (
  id    int          PRIMARY KEY,
  state ticket_state NOT NULL
);

INSERT INTO t_enum (id, state) VALUES (1, 'closed'), (2, 'open'), (3, 'triaged');

CREATE TABLE state_ref (
  code        text    PRIMARY KEY,
  label       text    NOT NULL,
  sort_order  int     NOT NULL,
  is_terminal boolean NOT NULL
);

INSERT INTO state_ref (code, label, sort_order, is_terminal) VALUES
  ('open', 'Open', 1, false),
  ('triaged', 'Triaged', 2, false),
  ('closed', 'Closed', 3, true);

CREATE TABLE t_ref (
  id    int  PRIMARY KEY,
  state text NOT NULL REFERENCES state_ref(code)
);

INSERT INTO t_ref (id, state) VALUES (1, 'closed'), (2, 'open'), (3, 'triaged');

SELECT id, state::text AS state
FROM t_enum
ORDER BY state, id;

SELECT t.id, t.state, r.label, r.is_terminal
FROM t_ref t
JOIN state_ref r ON r.code = t.state
ORDER BY r.sort_order, t.id;

-- Enum when the set is structural, tiny and code branches on each value:
-- ordering is free and the type system enforces membership. Lookup table
-- when values are data -- because only a table can carry attributes
-- (label, sort_order, is_terminal, translations) and let a non-engineer
-- add or retire a value; an enum can never drop one.

