SELECT s.id AS item_id, e.tag AS tag_name
FROM src s, jsonb_array_elements_text(s.doc -> 'tags') AS e(tag);

INSERT INTO tag (name) SELECT DISTINCT tag_name FROM pairs;

INSERT INTO item_tag (item_id, tag_name)
SELECT DISTINCT item_id, tag_name FROM pairs;

CREATE INDEX item_color_idx    ON item (color);
CREATE INDEX item_tag_name_idx ON item_tag (tag_name);

SELECT (SELECT count(*) FROM src)      AS src_rows,
       (SELECT count(*) FROM item)     AS item_rows,
       (SELECT count(*) FROM pairs)    AS src_tag_pairs,
       (SELECT count(*) FROM item_tag) AS item_tag_rows,
       (SELECT count(*) FROM src) = (SELECT count(*) FROM item)
         AND (SELECT count(*) FROM pairs) = (SELECT count(*) FROM item_tag)
         AS lossless;

-- v3c08_extensions / review1 — same inventory, keys read via jsonb_object_keys
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS hstore;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

SELECT extname::text    AS name,
       extversion::text AS version
FROM pg_extension
WHERE extname::text = ANY (ARRAY['citext','hstore','pgcrypto','pg_trgm','plpgsql'])
ORDER BY 1;

WITH total AS (SELECT count(*)::numeric AS n FROM events),
pairs AS (
  SELECT k.key AS key, ev.payload -> k.key AS value
  FROM events ev,
       jsonb_object_keys(ev.payload) AS k(key)
)
SELECT key,
       round(count(*) * 100.0 / (SELECT n FROM total), 1) AS pct_present,
       count(DISTINCT jsonb_typeof(value))                AS n_types
FROM pairs
GROUP BY key
ORDER BY key;
